DO $pilot_verify$
DECLARE mismatch boolean;
BEGIN
 WITH expected AS(SELECT * FROM jsonb_to_recordset('[{"t":"schema_migrations","n":"migration_id","ty":"character varying(128)"},{"t":"schema_migrations","n":"checksum","ty":"character(64)"},{"t":"schema_migrations","n":"applied_at","ty":"timestamp with time zone"},{"t":"pilot_budget_state","n":"pilot_id","ty":"character varying(64)"},{"t":"pilot_budget_state","n":"version","ty":"integer"},{"t":"pilot_budget_state","n":"max_calls","ty":"integer"},{"t":"pilot_budget_state","n":"used_calls","ty":"integer"},{"t":"pilot_budget_state","n":"input_tokens","ty":"bigint"},{"t":"pilot_budget_state","n":"output_tokens","ty":"bigint"},{"t":"pilot_budget_state","n":"live_model_verified","ty":"boolean"},{"t":"pilot_budget_state","n":"updated_at","ty":"timestamp with time zone"}]'::jsonb) x(t text,n text,ty text)), actual AS(
 SELECT r.relname t,a.attname n,format_type(a.atttypid,a.atttypmod) ty,a.attnotnull,a.atthasdef,a.attidentity,a.attgenerated FROM pg_attribute a JOIN pg_class r ON r.oid=a.attrelid JOIN pg_namespace s ON s.oid=r.relnamespace WHERE s.nspname='ai_pilot_v1' AND r.relkind='r' AND r.relname IN('schema_migrations','pilot_budget_state') AND a.attnum>0 AND NOT a.attisdropped)
 SELECT EXISTS(SELECT 1 FROM expected e FULL JOIN actual a USING(t,n) WHERE e.t IS NULL OR a.t IS NULL OR e.ty<>a.ty OR NOT a.attnotnull OR a.atthasdef OR a.attidentity<>'' OR a.attgenerated<>'') INTO mismatch;
 IF mismatch THEN RAISE EXCEPTION 'PILOT_SCHEMA_DRIFT columns'; END IF;
 WITH e AS(SELECT * FROM jsonb_to_recordset('[{"name":"pilot_migration_checksum_hex","def":"checkchecksum~''^[0-9a-f]{64}) x(name text,def text)), a AS(SELECT c.conname name,c.convalidated,replace(regexp_replace(lower(pg_get_constraintdef(c.oid,true)),'[[:space:]()]','','g'),'::text','') def FROM pg_constraint c JOIN pg_namespace n ON n.oid=c.connamespace WHERE n.nspname='ai_pilot_v1' AND c.contype='c')
 SELECT EXISTS(SELECT 1 FROM e FULL JOIN a USING(name,def) WHERE e.name IS NULL OR a.name IS NULL OR NOT a.convalidated) INTO mismatch;
 IF mismatch THEN RAISE EXCEPTION 'PILOT_SCHEMA_DRIFT checks'; END IF;
 IF (SELECT count(*) FROM pg_constraint c JOIN pg_namespace n ON n.oid=c.connamespace WHERE n.nspname='ai_pilot_v1')<>9 THEN RAISE EXCEPTION 'PILOT_SCHEMA_DRIFT constraints'; END IF;
 IF (SELECT count(*) FROM pg_index x JOIN pg_class t ON t.oid=x.indrelid JOIN pg_class i ON i.oid=x.indexrelid JOIN pg_am a ON a.oid=i.relam JOIN pg_namespace n ON n.oid=t.relnamespace WHERE n.nspname='ai_pilot_v1' AND x.indisprimary AND x.indisunique AND x.indisvalid AND x.indisready AND x.indnatts=1 AND x.indnkeyatts=1 AND x.indpred IS NULL AND x.indexprs IS NULL AND a.amname='btree' AND x.indkey::text='1')<>2 THEN RAISE EXCEPTION 'PILOT_SCHEMA_DRIFT primary indexes'; END IF;
 IF (SELECT count(*) FROM pg_index x JOIN pg_class t ON t.oid=x.indrelid JOIN pg_namespace n ON n.oid=t.relnamespace WHERE n.nspname='ai_pilot_v1')<>2 THEN RAISE EXCEPTION 'PILOT_SCHEMA_DRIFT indexes'; END IF;
 IF EXISTS(SELECT 1 FROM pg_trigger g JOIN pg_class t ON t.oid=g.tgrelid JOIN pg_namespace n ON n.oid=t.relnamespace WHERE n.nspname='ai_pilot_v1' AND NOT g.tgisinternal) THEN RAISE EXCEPTION 'PILOT_SCHEMA_DRIFT triggers'; END IF;
 IF NOT EXISTS(SELECT 1 FROM ai_pilot_v1.schema_migrations WHERE migration_id='P100_PILOT_BUDGET_001' AND checksum='aea079c308b56434929494b3a0ed479e82a93d130aa1b2e9c7f1ad1792e2cebf') THEN RAISE EXCEPTION 'PILOT_SCHEMA_DRIFT ledger'; END IF;
 IF (SELECT count(*) FROM ai_pilot_v1.pilot_budget_state)<>1 OR NOT EXISTS(SELECT 1 FROM ai_pilot_v1.pilot_budget_state WHERE pilot_id='GLOBAL_PILOT_100_V1' AND version=1 AND max_calls BETWEEN 1 AND 21 AND used_calls BETWEEN 0 AND max_calls AND input_tokens BETWEEN 0 AND 9007199254740991 AND output_tokens BETWEEN 0 AND 9007199254740991) THEN RAISE EXCEPTION 'PILOT_STATE_UNAVAILABLE'; END IF;
END;
$pilot_verify$;
'"},{"name":"pilot_singleton","def":"checkpilot_id=''global_pilot_100_v1''"},{"name":"pilot_version","def":"checkversion=1"},{"name":"pilot_hard_cap","def":"checkmax_calls>=1andmax_calls<=21"},{"name":"pilot_usage","def":"checkused_calls>=0andused_calls<=max_calls"},{"name":"pilot_input_tokens","def":"checkinput_tokens>=0andinput_tokens<=9007199254740991"},{"name":"pilot_output_tokens","def":"checkoutput_tokens>=0andoutput_tokens<=9007199254740991"}]'::jsonb) x(name text,def text)), a AS(SELECT c.conname name,c.convalidated,replace(regexp_replace(lower(pg_get_constraintdef(c.oid,true)),'[[:space:]()]','','g'),'::text','') def FROM pg_constraint c JOIN pg_namespace n ON n.oid=c.connamespace WHERE n.nspname='ai_pilot_v1' AND c.contype='c')
 SELECT EXISTS(SELECT 1 FROM e FULL JOIN a USING(name,def) WHERE e.name IS NULL OR a.name IS NULL OR NOT a.convalidated) INTO mismatch;
 IF mismatch THEN RAISE EXCEPTION 'PILOT_SCHEMA_DRIFT checks'; END IF;
 IF (SELECT count(*) FROM pg_constraint c JOIN pg_namespace n ON n.oid=c.connamespace WHERE n.nspname='ai_pilot_v1')<>9 THEN RAISE EXCEPTION 'PILOT_SCHEMA_DRIFT constraints'; END IF;
 IF (SELECT count(*) FROM pg_index x JOIN pg_class t ON t.oid=x.indrelid JOIN pg_class i ON i.oid=x.indexrelid JOIN pg_am a ON a.oid=i.relam JOIN pg_namespace n ON n.oid=t.relnamespace WHERE n.nspname='ai_pilot_v1' AND x.indisprimary AND x.indisunique AND x.indisvalid AND x.indisready AND x.indnatts=1 AND x.indnkeyatts=1 AND x.indpred IS NULL AND x.indexprs IS NULL AND a.amname='btree' AND x.indkey::text='1')<>2 THEN RAISE EXCEPTION 'PILOT_SCHEMA_DRIFT primary indexes'; END IF;
 IF (SELECT count(*) FROM pg_index x JOIN pg_class t ON t.oid=x.indrelid JOIN pg_namespace n ON n.oid=t.relnamespace WHERE n.nspname='ai_pilot_v1')<>2 THEN RAISE EXCEPTION 'PILOT_SCHEMA_DRIFT indexes'; END IF;
 IF EXISTS(SELECT 1 FROM pg_trigger g JOIN pg_class t ON t.oid=g.tgrelid JOIN pg_namespace n ON n.oid=t.relnamespace WHERE n.nspname='ai_pilot_v1' AND NOT g.tgisinternal) THEN RAISE EXCEPTION 'PILOT_SCHEMA_DRIFT triggers'; END IF;
 IF NOT EXISTS(SELECT 1 FROM ai_pilot_v1.schema_migrations WHERE migration_id='P100_PILOT_BUDGET_001' AND checksum='UP_CHECKSUM') THEN RAISE EXCEPTION 'PILOT_SCHEMA_DRIFT ledger'; END IF;
 IF (SELECT count(*) FROM ai_pilot_v1.pilot_budget_state)<>1 OR NOT EXISTS(SELECT 1 FROM ai_pilot_v1.pilot_budget_state WHERE pilot_id='GLOBAL_PILOT_100_V1' AND version=1 AND max_calls BETWEEN 1 AND 21 AND used_calls BETWEEN 0 AND max_calls AND input_tokens BETWEEN 0 AND 9007199254740991 AND output_tokens BETWEEN 0 AND 9007199254740991) THEN RAISE EXCEPTION 'PILOT_STATE_UNAVAILABLE'; END IF;
END;
$pilot_verify$;
